import {expandPlaceholder} from './sector-placeholder.js';
const $=id=>document.getElementById(id);let entries=[];
function render(){const query=$('search').value.toLowerCase(),shown=entries.filter(e=>(!$('role').value||e.role===$('role').value)&&(!$('feature').value||(e.config.feature?.kind||'land')===$('feature').value)&&(!$('progress').value||e.status===$('progress').value)&&e.id.includes(query));$('status').textContent=`${shown.length} of ${entries.length} configurations · ${entries.filter(e=>e.status==='authored').length} authored`;$('cards').replaceChildren();for(const e of shown){const article=document.createElement('article'),img=document.createElement('img');img.src=`sector-library/${e.id}/preview.svg`;img.alt=e.id;img.loading='lazy';const name=document.createElement('h2');name.textContent=e.id;const badge=document.createElement('small');badge.className='badge';badge.textContent=e.status;const detail=document.createElement('small');detail.textContent=`${e.difficulties.join(' / ')} · ${e.equivalents?.length||4} orientations`;const select=document.createElement('select');select.setAttribute('aria-label','Orientation for '+e.id);for(const [i,t]of e.allowedTransforms.entries()){const o=document.createElement('option');o.value=i;o.textContent=(t.mirror?'Mirror + ':'')+t.turns*90+'°';select.append(o);}const variants=document.createElement('select');variants.setAttribute('aria-label','Variant for '+e.id);for(const name of e.variants||['placeholder.json']){if(!/^[a-zA-Z0-9_-]+\.json$/.test(name))continue;const o=document.createElement('option');o.value=name;o.textContent=name;variants.append(o);}const open=document.createElement('a');open.textContent='Open in 3D editor';const update=()=>{const authored=variants.value!=='placeholder.json';select.disabled=authored;if(authored)select.value='0';open.href=`editor-3d.html?editing=1&sectorTemplate=${encodeURIComponent(e.id)}&orientation=${select.value}&variant=${encodeURIComponent(variants.value)}`;};select.onchange=variants.onchange=update;update();const download=document.createElement('button');download.textContent='Export full map';download.onclick=async()=>{if(variants.value!=='placeholder.json'){window.open(`sector-library/${e.id}/${variants.value}`,'_blank','noopener');return;}const map=expandPlaceholder(e,e.allowedTransforms[+select.value]),url=URL.createObjectURL(new Blob([JSON.stringify(map)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=e.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};article.append(img,name,badge,detail,variants,select,open,download);$('cards').append(article);}}
for(const id of ['search','role','feature','progress'])$(id).addEventListener('input',render);
try{const response=await fetch('sector-library/index.json');if(!response.ok)throw Error('Index unavailable');const index=await response.json();entries=await Promise.all(index.entries.map(async e=>{const r=await fetch(`sector-library/${e.id}/placeholder.json`);if(!r.ok)throw Error('Missing '+e.id);return r.json();}));render();}catch(e){$('status').textContent='Library could not load: '+e.message;}
